// Written in the cloud session 2026-11-03 (exam 11). Source of truth until ported to Claude/specs/lxd-course-ielts-exams/exam-11/.
(function(E){ const x = E["exam-11"] = E["exam-11"] || {units:{}}; (x.units = x.units || {})["x11-w1"] = {"id":"x11-w1","patterns":["W1-bar","W1-complaint","REG-semi","PARA-trend","PARA-letter","TR-overview","TR-bullets"],"title":{"en":"Writing Task 1","tr":"Writing Task 1","fa":"⁨Writing Task 1⁩ (نوشتن، تکلیف ۱)"},"objective":{"en":"After this lesson, you can describe a bar chart that compares three countries in two different years in at least 150 words: one overview of the trends they share, then the key figures grouped by category.","tr":"Bu dersin sonunda üç ülkeyi iki farklı yılda karşılaştıran bir sütun grafiğini, ortak eğilimler için tek bir genel bakış yazıp önemli rakamları kategoriye göre gruplayarak en az 150 kelimeyle anlatabileceksin.","fa":"بعد از این درس می‌توانی در دست‌کم ۱۵۰ کلمه یک نمودار میله‌ای را توصیف کنی که سه کشور را در دو سال مختلف مقایسه می‌کند: یک نمای کلی از روندهای مشترکشان و بعد عددهای مهم، دسته‌بندی‌شده بر اساس نوع هزینه."},"objectiveGT":{"en":"After this lesson, you can write a polite but firm letter to a neighbour about building work: explain how the noise affects you, describe a parking problem and suggest a solution, each in its own paragraph.","tr":"Bu dersin sonunda bir komşuna, gürültünün seni nasıl etkilediğini açıklayan, park sorununu anlatan ve bir çözüm öneren kibar ama kararlı bir mektubu, her maddeye ayrı bir paragraf vererek yazabileceksin.","fa":"بعد از این درس می‌توانی نامه‌ای مؤدبانه ولی محکم درباره‌ی کارهای ساختمانی به همسایه‌ات بنویسی: توضیح بدهی سروصدا چه اثری رویت دارد، مشکل جای پارک را شرح بدهی و راه‌حلی پیشنهاد کنی، هرکدام در پاراگراف خودش."},"sessions":[["explain"],["writing"],["exit"]],"explain":{"title":{"en":"Writing Task 1: three countries, two years","tr":"Writing Task 1: üç ülke, iki yıl","fa":"⁨Writing Task 1⁩: سه کشور، دو سال"},"objective":{"en":"After this lesson, you can describe a bar chart that compares three countries in two different years in at least 150 words: one overview of the trends they share, then the key figures grouped by category.","tr":"Bu dersin sonunda üç ülkeyi iki farklı yılda karşılaştıran bir sütun grafiğini, ortak eğilimler için tek bir genel bakış yazıp önemli rakamları kategoriye göre gruplayarak en az 150 kelimeyle anlatabileceksin.","fa":"بعد از این درس می‌توانی در دست‌کم ۱۵۰ کلمه یک نمودار میله‌ای را توصیف کنی که سه کشور را در دو سال مختلف مقایسه می‌کند: یک نمای کلی از روندهای مشترکشان و بعد عددهای مهم، دسته‌بندی‌شده بر اساس نوع هزینه."},"stats":[{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"150+"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Figures","tr":"Rakam","fa":"عدد"},"value":"24"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ زمینه"},"head":{"en":"This exam: household spending in three countries","tr":"Bu sınav: üç ülkede hane harcamaları","fa":"این آزمون: هزینه‌های خانوار در سه کشور"},"intro":{"en":"Bar charts that compare several countries in two different years are a regular Academic Task 1 visual. With 24 figures and only 150-200 words, the skill is choosing: first the trends the countries share, then the biggest differences.","tr":"Birkaç ülkeyi iki farklı yılda karşılaştıran sütun grafikler Academic Task 1’de düzenli olarak çıkar. 24 rakam ve yalnızca 150-200 kelimeyle asıl beceri seçmektir: önce ülkelerin ortak eğilimleri, sonra en büyük farklar.","fa":"نمودارهای میله‌ای که چند کشور را در دو سال مختلف مقایسه می‌کنند، مرتب در ⁨Academic Task 1⁩ می‌آیند. با ۲۴ عدد و فقط ۱۵۰ تا ۲۰۰ کلمه، مهارت اصلی انتخاب کردن است: اول روندهایی که بین کشورها مشترک است، بعد بزرگ‌ترین تفاوت‌ها."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب در آن‌هاست"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x11-w1-ctx","exam":true,"patterns":["W1-bar","PARA-trend"],"often":{"pattern":"W1-bar","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"One bar chart: how households divide their spending","tr":"Tek sütun grafik: haneler harcamalarını nasıl bölüştürüyor","fa":"یک نمودار میله‌ای: خانوارها هزینه‌هایشان را چطور تقسیم می‌کنند"},"asks":{"en":"The chart shows what share of household spending went on housing, food, transport and leisure in three countries, in 2000 and 2020. The figures are percentages of each household budget, so you describe shares and how they changed, not amounts of money.","tr":"Grafik, üç ülkede 2000 ve 2020 yıllarında hane harcamalarının ne kadarının konuta, gıdaya, ulaşıma ve boş zamana gittiğini gösteriyor. Rakamlar hane bütçesinin yüzdesidir; bu yüzden para miktarlarını değil, payları ve bu payların nasıl değiştiğini anlatırsın.","fa":"نمودار نشان می‌دهد در سه کشور، در سال‌های ۲۰۰۰ و ۲۰۲۰، چه سهمی از هزینه‌های خانوار صرف مسکن، غذا، حمل‌ونقل و تفریح شده است. عددها درصدی از بودجه‌ی خانوارند؛ پس سهم‌ها و تغییرشان را توصیف می‌کنی، نه مقدار پول را."},"fields":["What the chart measures: shares of spending","Trends shared by all three countries","The biggest differences between countries","Categories that hardly changed"],"words":[{"a":"household spending","b":"what families spend / household budgets","tr":"hane harcamaları","fa":"هزینه‌های خانوار"},{"a":"housing","b":"rent, mortgages and bills / the cost of a home","tr":"konut","fa":"مسکن"},{"a":"leisure","b":"free-time activities / entertainment and holidays","tr":"boş zaman","fa":"تفریح و اوقات فراغت"},{"a":"a share of 31%","b":"almost a third / just under a third","tr":"%31’lik pay","fa":"سهم ۳۱ درصدی"},{"a":"went on food","b":"was spent on food / was devoted to food","tr":"gıdaya harcandı","fa":"صرف غذا شد"},{"a":"the largest category","b":"the biggest expense / the main item of spending","tr":"en büyük kalem","fa":"بزرگ‌ترین دسته"},{"a":"from 24% to 33%","b":"a rise of nine percentage points","tr":"%24’ten %33’e","fa":"از ۲۴٪ به ۳۳٪"},{"a":"in every country","b":"in all three countries / everywhere","tr":"her ülkede","fa":"در هر کشور"},{"a":"overtook","b":"moved ahead of / became larger than","tr":"geçti","fa":"جلو زد"},{"a":"hardly changed","b":"remained stable / stayed at around","tr":"neredeyse değişmedi","fa":"تقریباً تغییری نکرد"},{"a":"the same proportion","b":"an equal share / matched","tr":"aynı oran","fa":"همان نسبت"},{"a":"over the period","b":"between 2000 and 2020 / over the two decades","tr":"bu dönem boyunca","fa":"در طول این دوره"}],"traps":[{"en":"Shares, not amounts: the bars are percentages of each budget. \"Country B spent more money on food\" may be false; write \"a larger share\" or \"a higher proportion\".","tr":"Miktar değil pay: Sütunlar her bütçenin yüzdesidir. \"Country B spent more money on food\" yanlış olabilir; \"a larger share\" ya da \"a higher proportion\" yaz.","fa":"سهم، نه مقدار: میله‌ها درصدی از بودجه‌اند. جمله‌ی «⁨Country B spent more money on food⁩» شاید غلط باشد؛ بنویس «⁨a larger share⁩» یا «⁨a higher proportion⁩»."},{"en":"Per cent or percentage points: housing in Country A went from 24% to 33%, a rise of nine percentage points, not of \"9%\".","tr":"Yüzde mi, yüzde puan mı: Country A’da konutun payı %24’ten %33’e çıktı. Bu, \"%9\"luk değil, dokuz yüzde puanlık bir artış.","fa":"درصد یا واحد درصد: سهم مسکن در ⁨Country A⁩ از ۲۴٪ به ۳۳٪ رسید؛ یعنی نُه واحد درصد افزایش، نه «۹٪»."},{"en":"A list of 24 numbers, country by country. Group the categories that behave alike in all three countries.","tr":"Ülke ülke sıralanmış 24 rakamlık bir liste. Üç ülkede de benzer davranan kategorileri grupla.","fa":"فهرستی از ۲۴ عدد، کشور به کشور. دسته‌هایی را که در هر سه کشور رفتار مشابهی دارند با هم گروه کن."}],"example":{"text":"Bar chart: share of spending on clothes. Country A: 8% (2000), 5% (2020). Country B: 7%, 6%. Country C: 9%, 5%.","item":"Which sentence groups the data better? (a) \"Country A was 8% and then 5%, Country B was 7% and then 6%, and Country C was 9% and then 5%.\" (b) \"The share spent on clothes fell in all three countries, most sharply in Country C, from 9% to 5%.\"","answer":"(b)","why":{"en":"(b) gives the shared trend first, then the most striking figure; (a) only lists numbers.","tr":"(b) önce ortak eğilimi, sonra en dikkat çekici rakamı veriyor; (a) yalnızca rakamları sıralıyor.","fa":"(⁨b⁩) اول روند مشترک را می‌گوید و بعد چشمگیرترین عدد را؛ (⁨a⁩) فقط عددها را ردیف می‌کند."}}},{"id":"W1-bar","ctx":["W1-bar"],"title":{"en":"Bar charts: comparing groups","tr":"Sütun grafikler: grupları karşılaştırma","fa":"نمودار میله‌ای: مقایسه‌ی گروه‌ها"},"asks":{"en":"Bars compare categories (countries, age groups, activities), often in two or more years. You need an overview of the biggest differences and changes, then figures grouped by pattern.","tr":"Sütunlar kategorileri (ülkeler, yaş grupları, etkinlikler) çoğu zaman iki ya da daha fazla yıl için karşılaştırır. En büyük farkların ve değişimlerin genel bakışı, sonra örüntüye göre gruplanmış rakamlar gerekir.","fa":"میله‌ها دسته‌ها (کشورها، گروه‌های سنی، فعالیت‌ها) را مقایسه می‌کنند، اغلب در دو سال یا بیشتر. یک نمای کلی از بزرگ‌ترین تفاوت‌ها و تغییرها لازم است، بعد عددها بر اساس الگو دسته‌بندی می‌شوند."},"fields":["Overview: highest and lowest categories, and the general change","The biggest differences between groups","The categories that changed most","The categories that stayed similar"],"words":[{"a":"the most","b":"the highest / the largest share","tr":"en yüksek","fa":"بیشترین"},{"a":"the least","b":"the lowest / the smallest proportion","tr":"en düşük","fa":"کمترین"},{"a":"bigger than","b":"higher than / exceeded","tr":"... -den yüksek","fa":"بیشتر از"},{"a":"twice as many","b":"double the number of","tr":"iki katı","fa":"دو برابرِ"},{"a":"the same as","b":"similar to / equal to","tr":"... ile aynı","fa":"مشابهِ"},{"a":"three out of ten","b":"30 per cent / just under a third","tr":"onda üç","fa":"سه نفر از هر ده نفر"},{"a":"a big difference","b":"a considerable gap","tr":"büyük bir fark","fa":"اختلاف زیاد"},{"a":"but","b":"whereas / while / in contrast","tr":"oysa","fa":"در حالی که"},{"a":"in that order","b":"respectively","tr":"sırasıyla","fa":"به ترتیب"},{"a":"each group","b":"every category","tr":"her kategori","fa":"هر دسته"},{"a":"the number for","b":"the figure for / the rate of","tr":"... rakamı","fa":"رقمِ"},{"a":"up 8 points","b":"increased by 8 percentage points","tr":"8 puan artış","fa":"۸ واحد درصد افزایش"}],"traps":[{"en":"\"Rose by\" gives the change; \"rose to\" gives the new figure. Do not mix them.","tr":"\"Rose by\" değişimi, \"rose to\" yeni rakamı verir. Karıştırma.","fa":"«⁨rose by⁩» مقدار تغییر را می‌گوید و «⁨rose to⁩» عدد جدید را. قاطی نکن."},{"en":"Do not describe the bars one by one from left to right; group the categories that behave alike.","tr":"Sütunları soldan sağa tek tek anlatma; benzer davranan kategorileri grupla.","fa":"میله‌ها را یکی‌یکی از چپ به راست توصیف نکن؛ دسته‌هایی را که رفتار مشابه دارند گروه کن."}],"example":{"text":"Bar chart: households with a dishwasher, 2000 and 2020. Country A: 35% and 70%. Country B: 50% and 52%.","item":"Compare the two countries in one sentence.","answer":"In Country A the proportion of households with a dishwasher doubled to 70%, whereas the figure for Country B barely changed, at around 50%.","why":{"en":"One sentence groups the big change and the stable figure, with \"doubled to\" and \"whereas\".","tr":"Tek cümle büyük değişimi ve sabit rakamı \"doubled to\" ve \"whereas\" ile birlikte veriyor.","fa":"یک جمله تغییر بزرگ و عدد ثابت را با «⁨doubled to⁩» و «⁨whereas⁩» کنار هم می‌گذارد."}},"general":true,"patterns":["W1-bar"],"often":{"pattern":"W1-bar","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Twenty minutes, 24 figures","tr":"Yirmi dakika, 24 rakam","fa":"بیست دقیقه، ۲۴ عدد"},"body":{"en":"Write at least 150 words in about 20 minutes. You cannot report all 24 figures, so choose. Plan four paragraphs: one sentence on what the chart shows, an overview of the shared trends, then two body paragraphs that group the categories.","tr":"Yaklaşık 20 dakikada en az 150 kelime yaz. 24 rakamın hepsini aktaramazsın, o yüzden seç. Dört paragraf planla: grafiğin ne gösterdiğini söyleyen bir cümle, ortak eğilimleri veren bir genel bakış, sonra kategorileri gruplayan iki gövde paragrafı.","fa":"در حدود ۲۰ دقیقه دست‌کم ۱۵۰ کلمه بنویس. نمی‌توانی همه‌ی ۲۴ عدد را گزارش کنی، پس انتخاب کن. چهار پاراگراف در نظر بگیر: یک جمله که می‌گوید نمودار چه نشان می‌دهد، یک نمای کلی از روندهای مشترک و بعد دو پاراگراف بدنه که دسته‌ها را گروه‌بندی می‌کنند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Read the title and the axis: these are shares of spending (%), not amounts of money.","tr":"Başlığı ve ekseni oku: Bunlar para miktarı değil, harcama paylarıdır (%).","fa":"عنوان و محور را بخوان: این‌ها سهم‌های هزینه‌اند (٪)، نه مقدار پول."},{"en":"Look across all three countries for what they share: what rose everywhere, and what fell everywhere.","tr":"Üç ülkeye birlikte bak ve ortak olanı bul: her yerde artanı ve her yerde azalanı.","fa":"به هر سه کشور با هم نگاه کن و چیز مشترک را پیدا کن: چه چیزی همه‌جا بالا رفت و چه چیزی همه‌جا پایین آمد."},{"en":"Write the overview first, straight after the opening sentence: the shared trends, with no figures.","tr":"Genel bakışı önce, açılış cümlesinin hemen ardından yaz: ortak eğilimler, rakamsız.","fa":"نمای کلی را اول بنویس، درست بعد از جمله‌ی شروع: روندهای مشترک، بدون عدد."},{"en":"Group the body paragraphs by category, the big categories first, and compare the countries inside each paragraph.","tr":"Gövde paragraflarını kategoriye göre grupla, büyük kategoriler önce gelsin; ülkeleri her paragrafın içinde karşılaştır.","fa":"پاراگراف‌های بدنه را بر اساس دسته گروه‌بندی کن، اول دسته‌های بزرگ، و کشورها را داخل هر پاراگراف با هم مقایسه کن."}],"tip":{"en":"Why it works: the overview is simply the trends all three countries share, so finding them first keeps it short and clear. The mistake: in English you spend money on something, never for it. Use spend on, spending on and the share spent on.","tr":"Neden işe yarar: Genel bakış, üç ülkenin ortak eğilimlerinden ibarettir; onları önce bulmak genel bakışı kısa ve net tutar. Hata: Türkçede «yemek için para harcamak» deriz, bu yüzden for yazılır. İngilizcede ise para bir şeye on ile harcanır: spend on, spending on, the share spent on.","fa":"این روش به کارت می‌آید، چون نمای کلی همان روندهایی است که هر سه کشور در آن مشترک‌اند و پیدا کردنشان در اول کار، نمای کلی را کوتاه و روشن نگه می‌دارد. اشتباه: در فارسی می‌گوییم «برای غذا خرج کردن» و همین «برای» در انگلیسی می‌شود ⁨for⁩. ولی در انگلیسی پول را ⁨on⁩ چیزی خرج می‌کنند: ⁨spend on⁩، ⁨spending on⁩، ⁨the share spent on⁩."},"wrong":"Households in Country B spent 31% of their budget for food.","right":"Households in Country B spent 31% of their budget on food."},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Shares and changes in shares","tr":"Paylar ve paylardaki değişim","fa":"سهم‌ها و تغییر سهم‌ها"},"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["a share at one time","In 2000, food took up almost a third of spending in Country B (31%)."],["a change in a share","The share spent on housing in Country A rose by nine percentage points, to 33%."],["the same trend everywhere","Spending on leisure grew in all three countries."],["a difference between countries","In 2000, Country C spent a larger proportion on transport than Country B."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"An overview for three countries","tr":"Üç ülke için bir genel bakış","fa":"نمای کلی برای سه کشور"},"instruction":"Bar chart: share of household spending on energy and on eating out, Countries A, B and C, 2000 and 2020. Energy fell in all three. Eating out rose in all three, most in Country B.","item":"Write a two-sentence overview.","answer":"Overall, the share of spending on energy fell in all three countries, while eating out took up a growing share everywhere. The rise in eating out was largest in Country B.","walk":[{"en":"Find what all three countries share: energy fell and eating out rose.","tr":"Üç ülkenin ortak noktasını bul: enerjinin payı düştü, dışarıda yemeğin payı arttı.","fa":"چیز مشترک هر سه کشور را پیدا کن: سهم انرژی پایین آمد و سهم غذا خوردن بیرون از خانه بالا رفت."},{"en":"Add one striking difference: the rise was largest in Country B.","tr":"Dikkat çeken tek bir farkı ekle: Artış en çok Country B’de oldu.","fa":"یک تفاوت چشمگیر اضافه کن: بیشترین افزایش در ⁨Country B⁩ بود."},{"en":"No figures: they belong in the body paragraphs.","tr":"Rakam yok: Rakamlar gövde paragraflarına aittir.","fa":"عدد نیاور: جای عددها در پاراگراف‌های بدنه است."}],"why":{"en":"Weak: \"In 2000, Country A spent 12% on energy and Country B spent 10%.\" It starts with details and has no main point. Strong: the overview below gives the shared trends first.","tr":"Zayıf: \"In 2000, Country A spent 12% on energy and Country B spent 10%.\" Ayrıntıyla başlıyor ve ana noktası yok. Güçlü: Aşağıdaki genel bakış önce ortak eğilimleri veriyor.","fa":"جمله‌ی «⁨In 2000, Country A spent 12% on energy and Country B spent 10%.⁩» با جزئیات شروع می‌شود و نکته‌ی اصلی ندارد. ولی نمای کلی پایین اول روندهای مشترک را می‌گوید."}},"quick":{"prompt":"In Country C, the share spent on housing went from 21% to 28%. Which sentence is accurate?","options":["It rose by 7%.","It rose by seven percentage points.","It rose to 7%."],"correct":1,"why":{"en":"The share went from 21 to 28, a change of seven percentage points. \"By 7%\" would mean a much smaller rise, and \"to 7%\" gives the wrong new figure.","tr":"Pay 21’den 28’e çıktı; bu yedi yüzde puanlık bir değişim. \"By 7%\" çok daha küçük bir artış anlamına gelir, \"to 7%\" ise yeni rakamı yanlış verir.","fa":"سهم از ۲۱ به ۲۸ رسید، یعنی هفت واحد درصد تغییر. «⁨by 7%⁩» یعنی افزایشی خیلی کوچک‌تر و «⁨to 7%⁩» عدد جدید را غلط می‌گوید."}},"remember":{"en":"Check what the bars measure, write the shared trends as the overview, then group the categories and compare the countries inside each paragraph. Result: you can now describe a bar chart of three countries and two years in one clear, selective answer.","tr":"Sütunların neyi ölçtüğüne bak, ortak eğilimleri genel bakış olarak yaz, sonra kategorileri grupla ve ülkeleri her paragrafın içinde karşılaştır. Sonuç: Artık üç ülkeyi ve iki yılı gösteren bir sütun grafiğini net ve seçici bir cevapla anlatabilirsin.","fa":"ببین میله‌ها چه چیزی را می‌سنجند، روندهای مشترک را به‌عنوان نمای کلی بنویس، بعد دسته‌ها را گروه‌بندی کن و کشورها را داخل هر پاراگراف مقایسه کن. نتیجه: حالا می‌توانی نمودار میله‌ای سه کشور در دو سال را در جوابی روشن و گزیده توصیف کنی."},"hook":{"en":"This Task 1 is one bar chart with 24 figures. The main idea: find what the three countries share, write it as your overview, and choose only the figures that support it.","tr":"Bu Task 1, 24 rakamlı tek bir sütun grafiktir. Ana fikir: Üç ülkenin ortak noktasını bul, onu genel bakış olarak yaz ve yalnızca onu destekleyen rakamları seç.","fa":"این ⁨Task 1⁩ یک نمودار میله‌ای با ۲۴ عدد است. چیزی را پیدا کن که هر سه کشور در آن مشترک‌اند، همان را نمای کلی‌ات کن و فقط عددهایی را بیاور که پشتیبانش هستند."},"type":"explain","id":"c-x11-w1-e","course":"ielts-exams","exam":"exam-11","unit":"x11-w1"},"writing":{"taskKind":"exam","title":{"en":"Describe the bar chart: household spending","tr":"Sütun grafiği anlat: hane harcamaları","fa":"نمودار میله‌ای را توصیف کن: هزینه‌های خانوار"},"task":"task1-academic","reviewLabel":{"en":"Exam 11 · Writing Task 1 Academic (bar chart: household spending in three countries, 2000 and 2020)"},"timed":20,"minWords":150,"ctx":["W1-bar"],"chart":{"type":"bar","title":"Illustrative figures: share of household spending on four categories in three countries, 2000 and 2020","unit":"%","labels":["Country A 2000","Country A 2020","Country B 2000","Country B 2020","Country C 2000","Country C 2020"],"series":[{"name":"Housing","values":[24,33,18,26,21,28]},{"name":"Food","values":[18,12,31,22,22,16]},{"name":"Transport","values":[14,13,9,14,16,12]},{"name":"Leisure","values":[9,11,5,8,12,16]}]},"prompt":{"en":"You should spend about 20 minutes on this task. The bar chart below shows the proportion of household spending that went on housing, food, transport and leisure in three countries in 2000 and 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.","tr":"Bu göreve yaklaşık 20 dakika ayırmalısın. Aşağıdaki sütun grafik, üç ülkede 2000 ve 2020 yıllarında hane harcamalarının ne kadarlık bir kısmının konuta, gıdaya, ulaşıma ve boş zamana gittiğini gösteriyor. Ana özellikleri seçip aktararak bilgiyi özetle ve gerekli yerlerde karşılaştırma yap. En az 150 kelime yaz.","fa":"باید حدود ۲۰ دقیقه برای این تکلیف وقت بگذاری. نمودار میله‌ای زیر نشان می‌دهد در سه کشور، در سال‌های ۲۰۰۰ و ۲۰۲۰، چه نسبتی از هزینه‌های خانوار صرف مسکن، غذا، حمل‌ونقل و تفریح شده است. اطلاعات را با انتخاب و گزارش ویژگی‌های اصلی خلاصه کن و هرجا لازم است مقایسه کن. دست‌کم ۱۵۰ کلمه بنویس."},"model":"The bar chart compares the proportion of household spending that went on housing, food, transport and leisure in three countries in 2000 and 2020.\n\nOverall, housing took a growing share of household budgets in all three countries and had become the largest category everywhere by 2020, while the share spent on food fell in each case. Leisure also accounted for a larger proportion of spending than before.\n\nIn 2000, food was the biggest expense in Country B, at 31%, and in Country C, at 22%, whereas households in Country A already spent more on housing (24%) than on anything else. Over the next twenty years, the share spent on housing rose by between seven and nine percentage points in every country, reaching 33% in Country A, 28% in Country C and 26% in Country B. Food followed the opposite pattern, with the sharpest fall in Country B, from 31% to 22%.\n\nThe figures for the two smaller categories were more varied. Transport took up a larger share in Country B by 2020 (14%, up from 9%) but a smaller one in Country C (down from 16% to 12%), and it hardly changed in Country A. Leisure, by contrast, grew in all three countries, and in Country C it reached 16%, the same proportion as food.","moves":[{"label":{"en":"1 What the chart shows","tr":"1 Grafik ne gösteriyor","fa":"۱ نمودار چه نشان می‌دهد"},"text":"The bar chart compares the proportion of household spending that went on housing, food, transport and leisure..."},{"label":{"en":"2 Overview first: the trends all three share","tr":"2 Önce genel bakış: üç ülkenin ortak eğilimleri","fa":"۲ اول نمای کلی: روندهای مشترک هر سه کشور"},"text":"Overall, housing took a growing share of household budgets in all three countries... while the share spent on food fell in each case."},{"label":{"en":"3 Body 1: the two big categories, compared","tr":"3 Gövde 1: iki büyük kategori, karşılaştırmalı","fa":"۳ بدنه ۱: دو دسته‌ی بزرگ، در مقایسه با هم"},"text":"In 2000, food was the biggest expense in Country B... Food followed the opposite pattern, with the sharpest fall in Country B..."},{"label":{"en":"4 Body 2: the smaller categories, grouped","tr":"4 Gövde 2: küçük kategoriler, gruplanmış","fa":"۴ بدنه ۲: دسته‌های کوچک‌تر، گروه‌بندی‌شده"},"text":"The figures for the two smaller categories were more varied... Leisure, by contrast, grew in all three countries..."}],"rubricBands":{"note":{"en":"Score each line from 0 to 3. Read the line for the score you choose: it tells you what to improve next.","tr":"Her satırı 0’dan 3’e puanla. Seçtiğin puanın satırını oku: bir sonraki adımda neyi geliştireceğini söyler.","fa":"به هر خط از ۰ تا ۳ نمره بده. توضیحِ نمره‌ای را که انتخاب می‌کنی بخوان: می‌گوید قدم بعدی چه چیزی را بهتر کنی."},"order":["task","organised","words","sentences"],"task":[{"en":"No overview, and key figures are missing or wrong.","tr":"Genel bakış yok; önemli rakamlar eksik ya da yanlış.","fa":"نمای کلی ندارد و عددهای مهم جا افتاده یا غلط‌اند."},{"en":"Some key features, but no clear overview, or every figure listed.","tr":"Bazı önemli noktalar var ama net bir genel bakış yok ya da her rakam sıralanmış.","fa":"بعضی نکته‌های مهم هست، اما نمای کلی روشنی نیست یا همه‌ی عددها فهرست شده‌اند."},{"en":"A clear overview and most key features, with figures.","tr":"Net bir genel bakış ve önemli noktaların çoğu, rakamlarla.","fa":"نمای کلی روشن و بیشترِ نکته‌های مهم، با عدد."},{"en":"A clear overview; all key features chosen well, compared, with accurate figures.","tr":"Net bir genel bakış; tüm önemli noktalar iyi seçilmiş, karşılaştırılmış, rakamlar doğru.","fa":"نمای کلی روشن؛ همه‌ی نکته‌های مهم خوب انتخاب و مقایسه شده‌اند و عددها دقیق‌اند."}],"organised":[{"en":"No paragraphs; ideas jump around.","tr":"Paragraf yok; fikirler bir yerden bir yere atlıyor.","fa":"پاراگراف ندارد؛ ایده‌ها پراکنده‌اند."},{"en":"Paragraphs, but the data is described item by item.","tr":"Paragraflar var ama veriler tek tek anlatılmış.","fa":"پاراگراف دارد، اما داده‌ها مورد به مورد توصیف شده‌اند."},{"en":"Introduction, overview and body paragraphs grouped by pattern.","tr":"Giriş, genel bakış ve örüntüye göre gruplanmış gövde paragrafları.","fa":"مقدمه، نمای کلی و پاراگراف‌هایی که بر اساس الگو دسته‌بندی شده‌اند."},{"en":"Every paragraph has one clear job; linking words are natural and varied.","tr":"Her paragrafın net bir işi var; bağlaçlar doğal ve çeşitli.","fa":"هر پاراگراف یک کار روشن دارد؛ کلمه‌های ربط طبیعی و متنوع‌اند."}],"words":[{"en":"Very few words for change; the question is copied.","tr":"Değişim için çok az kelime; soru kopyalanmış.","fa":"کلمه‌های خیلی کمی برای تغییر؛ صورت سؤال کپی شده."},{"en":"The same few words (increase, decrease) again and again.","tr":"Aynı birkaç kelime (increase, decrease) tekrar tekrar.","fa":"همان چند کلمه (⁨increase⁩، ⁨decrease⁩) مدام تکرار شده."},{"en":"Varied words for change and comparison, with a few errors.","tr":"Değişim ve karşılaştırma için çeşitli kelimeler, birkaç hatayla.","fa":"کلمه‌های متنوع برای تغییر و مقایسه، با چند غلط."},{"en":"Precise, varied words for trends and comparison, almost no errors.","tr":"Eğilim ve karşılaştırma için kesin, çeşitli kelimeler, neredeyse hatasız.","fa":"کلمه‌های دقیق و متنوع برای روند و مقایسه، تقریباً بی‌غلط."}],"sentences":[{"en":"Mostly short sentences with frequent errors.","tr":"Çoğunlukla kısa cümleler, sık hatalar.","fa":"بیشتر جمله‌های کوتاه با غلط‌های زیاد."},{"en":"Some longer sentences; errors sometimes make the meaning unclear.","tr":"Bazı uzun cümleler; hatalar bazen anlamı belirsizleştiriyor.","fa":"چند جمله‌ی بلندتر؛ غلط‌ها گاهی معنی را نامفهوم می‌کنند."},{"en":"A mix of sentence types; errors rarely affect the meaning.","tr":"Çeşitli cümle türleri; hatalar anlamı nadiren etkiliyor.","fa":"ترکیبی از انواع جمله؛ غلط‌ها به‌ندرت روی معنی اثر می‌گذارند."},{"en":"A wide range of sentences, almost all accurate.","tr":"Çok çeşitli cümleler, neredeyse hepsi doğru.","fa":"جمله‌های خیلی متنوع، تقریباً همه درست."}]},"rubric":["Covers the task: an overview of the main trends or stages and the key features, with accurate figures.","Organised: an introduction, an overview, then body paragraphs grouped by pattern, not item by item.","Words: varied language for change and comparison, spelled correctly; the prompt is not copied.","Sentences: a mix of simple and complex sentences; tenses and the prepositions to and by used correctly."],"rubricI18n":{"tr":["Görevi karşılıyor: ana eğilimlerin ya da aşamaların ve önemli özelliklerin genel bakışı, doğru rakamlarla.","Düzenli: giriş, genel bakış, sonra tek tek değil örüntüye göre gruplanmış gövde paragrafları.","Kelimeler: değişim ve karşılaştırma için çeşitli ifadeler, doğru yazılmış; soru metni kopyalanmamış.","Cümleler: basit ve karmaşık cümlelerin karışımı; zamanlar ve to ile by edatları doğru kullanılmış."],"fa":["تکلیف را پوشش می‌دهد: نمای کلی روندها یا مرحله‌های اصلی و ویژگی‌های مهم، با عددهای دقیق.","منظم است: مقدمه، نمای کلی، بعد پاراگراف‌هایی که بر اساس الگو دسته‌بندی شده‌اند، نه مورد به مورد.","کلمه‌ها: زبان متنوع برای تغییر و مقایسه، با املای درست؛ متن سؤال کپی نشده.","جمله‌ها: ترکیبی از جمله‌های ساده و مرکب؛ زمان‌ها و حرف‌های اضافه‌ی ⁨to⁩ و ⁨by⁩ درست به کار رفته‌اند."]},"type":"writing","id":"c-x11-w1-w","course":"ielts-exams","exam":"exam-11","unit":"x11-w1"},"exit":{"type":"exit","items":[{"tests":"word","point":3,"prompt":"\"Food took up almost a third of spending.\" Took up means...","options":["formed that part of the total","rose to","cost less than"],"correct":0,"why":{"en":"Took up = formed that part of the total, like made up or accounted for.","tr":"Took up = toplamın o kısmını oluşturdu; made up ya da accounted for gibi.","fa":"⁨took up⁩ یعنی آن بخش از کل را تشکیل داد، مثل ⁨made up⁩ یا ⁨accounted for⁩."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means the same as \"31%\"?","options":["just over a quarter","just under a third","almost half"],"correct":1,"why":{"en":"A third is about 33%, so 31% is just under a third. A quarter is 25%; almost half would be about 48%.","tr":"Üçte bir yaklaşık %33’tür; yani %31 üçte birin biraz altıdır. Çeyrek %25’tir; neredeyse yarısı %48 civarı olurdu.","fa":"یک‌سوم حدود ۳۳٪ است، پس ۳۱٪ کمی کمتر از یک‌سوم است. یک‌چهارم ۲۵٪ است و تقریباً نصف یعنی حدود ۴۸٪."}},{"tests":"method","point":2,"prompt":"What should the overview of this chart contain?","options":["the trends shared by all three countries, with no figures","the figures for Country A in 2000","the reasons why housing became more expensive"],"correct":0,"why":{"en":"An overview gives the main trends only. Figures go in the body, and the chart gives no reasons.","tr":"Genel bakış yalnızca ana eğilimleri verir. Rakamlar gövdeye girer; grafik de neden vermez.","fa":"نمای کلی فقط روندهای اصلی را می‌گوید. عددها مال بدنه‌اند و نمودار هم دلیلی نشان نمی‌دهد."}},{"tests":"trap","point":2,"prompt":"A student writes: \"Households in Country B spent 31% of their budget for food.\" What is wrong?","options":["31% should be 22%","\"for food\" should be \"on food\"","\"households\" should be \"countries\""],"correct":1,"why":{"en":"You spend money on something. In 2000 the figure for Country B was 31%, so the number is right.","tr":"Para bir şeye on ile harcanır. 2000’de Country B’nin rakamı %31’di; yani sayı doğru.","fa":"پول را ⁨on⁩ چیزی خرج می‌کنند. رقم ⁨Country B⁩ در سال ۲۰۰۰ برابر ۳۱٪ بود؛ پس عدد درست است."}}],"id":"c-x11-w1-x","course":"ielts-exams","exam":"exam-11","unit":"x11-w1"},"gt":{"explain":{"title":{"en":"Writing Task 1 (GT): building work next door","tr":"Writing Task 1 (GT): yan evdeki tadilat","fa":"⁨Writing Task 1⁩ (⁨GT⁩): کارهای ساختمانی خانه‌ی بغلی"},"objective":{"en":"After this lesson, you can write a polite but firm letter to a neighbour about building work: explain how the noise affects you, describe a parking problem and suggest a solution, each in its own paragraph.","tr":"Bu dersin sonunda bir komşuna, gürültünün seni nasıl etkilediğini açıklayan, park sorununu anlatan ve bir çözüm öneren kibar ama kararlı bir mektubu, her maddeye ayrı bir paragraf vererek yazabileceksin.","fa":"بعد از این درس می‌توانی نامه‌ای مؤدبانه ولی محکم درباره‌ی کارهای ساختمانی به همسایه‌ات بنویسی: توضیح بدهی سروصدا چه اثری رویت دارد، مشکل جای پارک را شرح بدهی و راه‌حلی پیشنهاد کنی، هرکدام در پاراگراف خودش."},"stats":[{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"150+"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Bullet points","tr":"Madde","fa":"نکته‌ها"},"value":"3"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ زمینه"},"head":{"en":"This exam: building work next door","tr":"Bu sınav: yan evdeki tadilat","fa":"این آزمون: کارهای ساختمانی خانه‌ی بغلی"},"intro":{"en":"Complaints are among the most frequent GT letter types. A letter to a neighbour is a special case: you want the problem solved, but you will go on living next door, so the tone is semi-formal: polite, friendly and clear about the facts.","tr":"Şikâyetler en sık çıkan GT mektup türleri arasındadır. Komşuya yazılan mektup özel bir durumdur: Sorunun çözülmesini istersin ama yan yana yaşamaya devam edeceksiniz. Bu yüzden üslup yarı resmîdir: kibar, samimi ve olgular konusunda net.","fa":"شکایت از رایج‌ترین نوع‌های نامه‌ی ⁨GT⁩ است. نامه به همسایه حالت خاصی دارد: می‌خواهی مشکل حل شود، اما باز هم قرار است کنار هم زندگی کنید؛ پس لحن نیمه‌رسمی است: مؤدب، دوستانه و درباره‌ی واقعیت‌ها روشن."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب در آن‌هاست"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x11-w1gt-ctx","exam":true,"patterns":["W1-complaint","REG-semi","PARA-letter"],"often":{"pattern":"W1-complaint","n":9,"of":36,"label":{"en":"Comes up often in the real exam: 9 of the last 36 letters","tr":"Gerçek sınavda sık çıkar: son 36 mektubun 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ نامه از ۳۶ نامه‌ی اخیر"}},"title":{"en":"A polite complaint to a neighbour","tr":"Komşuya kibar bir şikâyet","fa":"شکایتی مؤدبانه به همسایه"},"asks":{"en":"Your neighbour is having building work done. You write about the noise and the early starts, a problem with parking, and what could be done about them. You know the reader’s name, so the letter is semi-formal: friendly, but every problem has a clear fact, such as a time, a day or an effect.","tr":"Komşun evinde tadilat yaptırıyor. Gürültü ve sabahın erken saatinde başlayan çalışma, bir park sorunu ve bunlar için neler yapılabileceği hakkında yazıyorsun. Okurun adını biliyorsun; bu yüzden mektup yarı resmîdir: samimi, ama her sorunun bir saat, bir gün ya da bir sonuç gibi net bir olgusu var.","fa":"همسایه‌ات در خانه‌اش کار ساختمانی راه انداخته. درباره‌ی سروصدا و شروع کار در ساعت‌های خیلی زود، یک مشکل جای پارک و کاری که برای حلشان می‌شود کرد نامه می‌نویسی. اسم خواننده را می‌دانی، پس نامه نیمه‌رسمی است: دوستانه، ولی هر مشکل یک واقعیت روشن دارد، مثل یک ساعت، یک روز یا یک پیامد."},"fields":["Opening: a friendly line, then the purpose","Noise and early starts: times and effects","Parking: one clear example","A solution: polite suggestions","A friendly close"],"words":[{"a":"the building work","b":"the extension / the work on your house","tr":"tadilat","fa":"کارهای ساختمانی"},{"a":"noise","b":"drilling and hammering / the noise from the site","tr":"gürültü","fa":"سروصدا"},{"a":"too early","b":"from seven in the morning / before most people are up","tr":"çok erken","fa":"خیلی زود"},{"a":"I can't sleep","b":"I have hardly slept / it wakes the baby up","tr":"uyuyamıyorum","fa":"نمی‌توانم بخوابم"},{"a":"their cars","b":"the builders' vans / delivery lorries","tr":"arabaları","fa":"ماشین‌هایشان"},{"a":"I can't get my car out","b":"they block our drive","tr":"arabamı çıkaramıyorum","fa":"نمی‌توانم ماشینم را بیرون بیاورم"},{"a":"a request","b":"would it be possible to ...? / I wonder if ...","tr":"rica","fa":"درخواست"},{"a":"start later","b":"not start the noisy work before nine","tr":"daha geç başlamak","fa":"دیرتر شروع کردن"},{"a":"park somewhere else","b":"use the side road / the car park behind the shops","tr":"başka bir yere park etmek","fa":"جای دیگری پارک کردن"},{"a":"end (known name, friendly)","b":"Kind regards / Best wishes","tr":"bitiş (isim biliniyor, samimi)","fa":"پایان (اسم معلوم، دوستانه)"}],"traps":[{"en":"An angry tone. \"This is unacceptable!\" may suit a company, but not someone you will meet at the gate tomorrow. Be firm with the facts and polite with the words.","tr":"Öfkeli bir üslup. \"This is unacceptable!\" bir şirkete uyabilir ama yarın kapıda karşılaşacağın birine uymaz. Olgularda kararlı, sözlerde kibar ol.","fa":"لحن عصبانی. «⁨This is unacceptable!⁩» شاید برای یک شرکت مناسب باشد، ولی نه برای کسی که فردا دم در می‌بینی‌اش. در واقعیت‌ها محکم باش و در کلمه‌ها مؤدب."},{"en":"A vague solution: \"Please do something.\" Suggest something specific and easy to agree to: a later start, another place to park.","tr":"Belirsiz bir çözüm: \"Please do something.\" Somut ve kabul etmesi kolay bir şey öner: daha geç bir başlangıç saati, park etmek için başka bir yer.","fa":"راه‌حل مبهم: «⁨Please do something.⁩» چیزی مشخص و راحت‌پذیرفتنی پیشنهاد کن: شروع دیرتر یا جای دیگری برای پارک."}],"example":{"text":"Bullet: \"suggest what could be done to solve these problems\"","item":"Which sentence works better? (a) \"You must stop the noise immediately.\" (b) \"Would it be possible to ask the builders not to start the noisy work before nine?\"","answer":"(b)","why":{"en":"(b) is specific and polite, so it is easy to agree to; (a) is an order.","tr":"(b) somut ve kibar, bu yüzden kabul etmesi kolay; (a) bir emir.","fa":"(⁨b⁩) مشخص و مؤدبانه است و راحت می‌شود با آن موافقت کرد؛ (⁨a⁩) دستور است."}}},{"id":"W1-comp-neighbour","ctx":["W1-complaint","W1-comp-neighbour"],"title":{"en":"Problems where you live","tr":"Yaşadığın yerdeki sorunlar","fa":"مشکل‌های محل زندگی"},"asks":{"en":"You write to a neighbour, a landlord or a building manager about noise, parking, rubbish, a shared garden or a repair that has not been done. If you know the reader, the letter is semi-formal: polite and friendly, but clear about the problem and what you would like.","tr":"Bir komşuya, ev sahibine ya da apartman yöneticisine gürültü, park, çöp, ortak bahçe ya da yapılmamış bir onarım hakkında yazarsın. Okuru tanıyorsan mektup yarı resmîdir: kibar ve samimi, ama sorun ve ne istediğin konusunda net.","fa":"به همسایه، صاحب‌خانه یا مدیر ساختمان درباره‌ی سروصدا، جای پارک، زباله، حیاط مشترک یا تعمیری که انجام نشده نامه می‌نویسی. اگر خواننده را می‌شناسی، نامه نیمه‌رسمی است: مؤدب و دوستانه، ولی درباره‌ی مشکل و چیزی که می‌خواهی روشن."},"fields":["Opening: who you are and why you are writing","The problem: what, when and how often","The effect on you or your family","What you would like: one or two clear requests","Ending: friendly, hoping to sort it out"],"words":[{"a":"I live next door","b":"I live at number 14 / your neighbour at number 14","tr":"yan evde oturuyorum","fa":"خانه‌ی بغلی زندگی می‌کنم"},{"a":"loud music","b":"music late at night / parties until 2 a.m.","tr":"yüksek sesli müzik","fa":"موسیقی با صدای بلند"},{"a":"often","b":"three or four times a week / most weekends","tr":"sık sık","fa":"اغلب"},{"a":"rubbish","b":"bin bags left in the shared hallway","tr":"çöp","fa":"زباله"},{"a":"broken","b":"has not worked since March / still needs repairing","tr":"bozuk","fa":"خراب"},{"a":"the owner of the flat","b":"the landlord / the letting agent","tr":"dairenin sahibi","fa":"صاحب آپارتمان"},{"a":"it is a problem for us","b":"it has been difficult for us because","tr":"bu bizim için bir sorun","fa":"این برای ما مشکل است"},{"a":"I don't want to argue","b":"I'm sure it wasn't intentional","tr":"tartışmak istemiyorum","fa":"نمی‌خواهم بحث کنم"},{"a":"please","b":"I would be grateful if ...","tr":"lütfen","fa":"لطفاً"},{"a":"talk about it","b":"perhaps we could have a chat about it","tr":"bunu konuşmak","fa":"درباره‌اش حرف زدن"},{"a":"soon","b":"in the next few days / before the weekend","tr":"yakında","fa":"به‌زودی"},{"a":"end (known name)","b":"Kind regards / Best wishes","tr":"bitiş (isim biliniyorsa)","fa":"پایان (اسم معلوم)"}],"traps":[{"en":"Too formal or too cold: \"Dear Sir or Madam\" and \"I demand\" sound strange to a neighbour you know. Use their name and a friendly first line.","tr":"Fazla resmî ya da soğuk: \"Dear Sir or Madam\" ve \"I demand\" tanıdığın bir komşuya tuhaf gelir. Adını ve samimi bir ilk cümle kullan.","fa":"زیادی رسمی یا سرد: «⁨Dear Sir or Madam⁩» و «⁨I demand⁩» برای همسایه‌ای که می‌شناسی عجیب است. اسمش را بیاور و با یک جمله‌ی دوستانه شروع کن."},{"en":"Too soft: so polite that the problem is unclear. Give the facts: what happens, when and how often.","tr":"Fazla yumuşak: o kadar kibar ki sorun anlaşılmıyor. Olguları ver: ne oluyor, ne zaman ve ne sıklıkla.","fa":"زیادی نرم: آن‌قدر مؤدب که مشکل معلوم نیست. واقعیت‌ها را بگو: چه اتفاقی می‌افتد، کی و هر چند وقت یک بار."}],"example":{"text":"Bullet: \"explain how the problem is affecting you\".","item":"Which sentence covers it best?  A It is not very nice.   B The music usually goes on until about two in the morning, and as I start work at seven, I have been exhausted all week.   C I am extremely angry.","answer":"B","why":{"en":"B gives a time, a cause and a clear effect; A is vague and C is only a feeling.","tr":"B bir saat, bir neden ve net bir sonuç veriyor; A belirsiz, C ise yalnızca bir duygu.","fa":"⁨B⁩ ساعت، علت و پیامدی روشن را می‌گوید؛ ⁨A⁩ مبهم است و ⁨C⁩ فقط یک احساس."}},"general":true,"patterns":["W1-complaint"],"often":{"pattern":"W1-complaint","n":9,"of":36,"label":{"en":"Comes up often in the real exam: 9 of the last 36 letters","tr":"Gerçek sınavda sık çıkar: son 36 mektubun 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ نامه از ۳۶ نامه‌ی اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"A friendly opening, three bullets, a friendly close","tr":"Samimi bir açılış, üç madde, samimi bir kapanış","fa":"شروع دوستانه، سه نکته، پایان دوستانه"},"body":{"en":"Write at least 150 words in about 20 minutes. Begin with your neighbour’s name, for example \"Dear Mr Hartley,\", and end \"Kind regards,\" and your full name. Open with one friendly sentence and your reason for writing, then give each bullet its own paragraph.","tr":"Yaklaşık 20 dakikada en az 150 kelime yaz. Komşunun adıyla başla, örneğin \"Dear Mr Hartley,\"; \"Kind regards,\" ve tam adınla bitir. Samimi bir cümle ve yazma nedeninle aç, sonra her maddeye kendi paragrafını ver.","fa":"در حدود ۲۰ دقیقه دست‌کم ۱۵۰ کلمه بنویس. با اسم همسایه‌ات شروع کن، مثلاً «⁨Dear Mr Hartley,⁩»، و با «⁨Kind regards,⁩» و اسم کاملت تمام کن. با یک جمله‌ی دوستانه و دلیل نوشتنت شروع کن و بعد به هر نکته پاراگراف خودش را بده."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Open with one friendly line, then say why you are writing: the building work is causing some problems.","tr":"Samimi bir cümleyle aç, sonra neden yazdığını söyle: Tadilat bazı sorunlara yol açıyor.","fa":"با یک جمله‌ی دوستانه شروع کن، بعد بگو چرا می‌نویسی: کارهای ساختمانی چند مشکل درست کرده."},{"en":"For the noise and the early starts, give facts: when it starts, what you hear and who it affects.","tr":"Gürültü ve erken başlama için olguları ver: ne zaman başlıyor, ne duyuyorsun ve kimi etkiliyor.","fa":"برای سروصدا و شروع زودهنگام، واقعیت‌ها را بگو: کی شروع می‌شود، چه می‌شنوی و روی چه کسی اثر می‌گذارد."},{"en":"For parking, give one clear example: what happened, when, and the result.","tr":"Park için tek bir net örnek ver: ne oldu, ne zaman ve sonucu ne oldu.","fa":"برای جای پارک یک مثال روشن بیاور: چه شد، کی و نتیجه‌اش چه بود."},{"en":"For the solution, make one or two specific suggestions as polite questions: Would it be possible to...? Could the builders...?","tr":"Çözüm için bir iki somut öneriyi kibar sorular olarak yaz: Would it be possible to...? Could the builders...?","fa":"برای راه‌حل، یکی دو پیشنهاد مشخص را به شکل سؤال مؤدبانه بنویس: ⁨Would it be possible to...?⁩، ⁨Could the builders...?⁩"}],"tip":{"en":"Why it works: facts make the problem clear without anger, and a polite question is easy to say yes to. The mistake: tell is followed directly by the person, with no \"to\": tell the builders, tell him. (With say, you do use to: say it to him.)","tr":"Neden işe yarar: Olgular sorunu öfkeye kapılmadan netleştirir; kibar bir soruya evet demek de kolaydır. Hata: Türkçede «işçilere söyle» deriz ve -e eki İngilizceye to olarak geçer. Oysa tell’den hemen sonra kişi gelir, to gelmez: tell the builders, tell him. (say ile to kullanılır: say it to him.)","fa":"این روش به کارت می‌آید، چون واقعیت‌ها مشکل را بدون عصبانیت روشن می‌کنند و به یک سؤال مؤدبانه راحت می‌شود جواب مثبت داد. اشتباه: در فارسی می‌گوییم «به کارگرها بگو» و همین «به» در انگلیسی می‌شود ⁨to⁩. اما بعد از ⁨tell⁩ مستقیم خود شخص می‌آید، بدون ⁨to: tell the builders⁩، ⁨tell him⁩. (با ⁨say⁩ باید ⁨to⁩ بیاید: ⁨say it to him⁩.)"},"wrong":"Could you tell to the builders to start a little later?","right":"Could you tell the builders to start a little later?"},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Firm facts, polite requests","tr":"Kararlı olgular, kibar ricalar","fa":"واقعیت‌های محکم، درخواست‌های مؤدبانه"},"table":{"headers":{"en":["Too direct","Semi-formal and polite"],"tr":["Fazla doğrudan","Yarı resmî ve kibar"],"fa":["خیلی مستقیم","نیمه‌رسمی و مؤدبانه"]},"rows":[["Your builders are too loud.","The drilling starts at about seven, and it wakes our baby every morning."],["Stop parking in front of my house.","Would it be possible for the vans to use the side road instead?"],["You must fix this now.","I hope we can find a solution that works for both of us."],["I want an answer.","Do knock on our door if you would like to talk about it."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"The solution paragraph, step by step","tr":"Çözüm paragrafı, adım adım","fa":"پاراگراف راه‌حل، قدم به قدم"},"instruction":"Bullet: \"suggest what could be done to solve these problems\"","item":"Write two sentences for this bullet.","answer":"Would it be possible to ask the builders not to start the noisy work before nine? It would also help a great deal if they could park on the side road behind the shops, where there is usually plenty of space.","walk":[{"en":"Start with the problem that matters most: the early noise.","tr":"En önemli sorunla başla: sabahın erken saatindeki gürültü.","fa":"با مهم‌ترین مشکل شروع کن: سروصدای صبح زود."},{"en":"Turn the suggestion into a polite question: \"Would it be possible to...?\"","tr":"Öneriyi kibar bir soruya çevir: \"Would it be possible to...?\"","fa":"پیشنهاد را به یک سؤال مؤدبانه تبدیل کن: «⁨Would it be possible to...?⁩»"},{"en":"Make the second suggestion easy to accept: name a real place to park.","tr":"İkinci öneriyi kabul edilmesi kolay yap: Park etmek için gerçek bir yer söyle.","fa":"پیشنهاد دوم را راحت‌پذیرفتنی کن: یک جای واقعی برای پارک نام ببر."}],"why":{"en":"Weak: \"Please stop making noise and stop parking there.\" It sounds like an order and gives no alternative. Strong: the sentences below suggest a clear alternative that is easy to accept.","tr":"Zayıf: \"Please stop making noise and stop parking there.\" Emir gibi duruyor ve bir seçenek sunmuyor. Güçlü: Aşağıdaki cümleler kabul edilmesi kolay, net bir seçenek öneriyor.","fa":"جمله‌ی «⁨Please stop making noise and stop parking there.⁩» مثل دستور است و راه دیگری پیشنهاد نمی‌دهد. ولی جمله‌های پایین راه دیگری روشن و راحت‌پذیرفتنی پیشنهاد می‌کنند."}},"quick":{"prompt":"Which opening suits a letter to a neighbour you know?","options":["Dear Sir or Madam, I am writing to make a formal complaint.","Dear Mr Hartley, I hope the work on your extension is going well, but I'm afraid it is causing us a few problems.","Hi! Your builders are driving us crazy."],"correct":1,"why":{"en":"It uses the name, starts in a friendly way and still states the problem. The first is too formal for a neighbour; the third is rude.","tr":"Adı kullanıyor, samimi başlıyor ve yine de sorunu söylüyor. Birincisi bir komşu için fazla resmî, üçüncüsü kaba.","fa":"اسم را می‌آورد، دوستانه شروع می‌کند و باز هم مشکل را می‌گوید. اولی برای همسایه زیادی رسمی است و سومی بی‌ادبانه."}},"remember":{"en":"A friendly opening, facts for each problem, and a solution as a polite question. Result: you can now write a firm but friendly letter that asks a neighbour to solve a problem.","tr":"Samimi bir açılış, her sorun için olgular ve kibar bir soru olarak çözüm. Sonuç: Artık bir komşudan bir sorunu çözmesini isteyen, kararlı ama samimi bir mektup yazabilirsin.","fa":"شروعی دوستانه، واقعیت‌ها برای هر مشکل و راه‌حل در قالب یک سؤال مؤدبانه. نتیجه: حالا می‌توانی نامه‌ای محکم ولی دوستانه بنویسی و از همسایه‌ات بخواهی مشکلی را حل کند."},"hook":{"en":"This letter asks a neighbour to solve the problems their building work is causing. The main idea: be clear about the facts and friendly in tone, because you will still be neighbours tomorrow.","tr":"Bu mektup bir komşudan, tadilatın yol açtığı sorunları çözmesini istiyor. Ana fikir: Olgular konusunda net, üslupta samimi ol; çünkü yarın da komşu olacaksınız.","fa":"این نامه از همسایه می‌خواهد مشکل‌هایی را که کارهای ساختمانی‌اش درست کرده حل کند. درباره‌ی واقعیت‌ها روشن باش و لحنت دوستانه باشد، چون فردا هم همسایه‌اید."},"type":"explain","id":"c-x11-w1-e-gt","course":"ielts-exams","exam":"exam-11","unit":"x11-w1"},"writing":{"taskKind":"exam","title":{"en":"Write to your neighbour about the building work","tr":"Komşuna tadilat hakkında yaz","fa":"درباره‌ی کارهای ساختمانی به همسایه‌ات نامه بنویس"},"task":"task1-gt","reviewLabel":{"en":"Exam 11 · Writing Task 1 GT (semi-formal letter: building work next door)"},"timed":20,"minWords":150,"ctx":["W1-complaint","REG-semi"],"bullets":["explain how the noise and the early starts are affecting you","describe the problem with parking","suggest what could be done to solve these problems"],"prompt":{"en":"You should spend about 20 minutes on this task. Your neighbour is having building work done on their house, and the work is causing you some problems. Write a letter to your neighbour. In your letter: explain how the noise and the early starts are affecting you; describe the problem with parking; suggest what could be done to solve these problems. Write at least 150 words. You do NOT need to write any addresses. Begin your letter as follows: Dear ...............,","tr":"Bu göreve yaklaşık 20 dakika ayırmalısın. Komşun evinde tadilat yaptırıyor ve bu çalışmalar sana bazı sorunlar çıkarıyor. Komşuna bir mektup yaz. Mektubunda: gürültünün ve sabahın erken saatinde başlayan çalışmaların seni nasıl etkilediğini açıkla; park sorununu anlat; bu sorunları çözmek için neler yapılabileceğini öner. En az 150 kelime yaz. Adres yazmana gerek yok. Mektuba şöyle başla: Dear ...............,","fa":"باید حدود ۲۰ دقیقه برای این تکلیف وقت بگذاری. همسایه‌ات در خانه‌اش کار ساختمانی انجام می‌دهد و این کار برایت چند مشکل درست کرده. برای همسایه‌ات نامه بنویس. در نامه‌ات: توضیح بده سروصدا و شروع کار در ساعت‌های خیلی زود چه اثری رویت دارد؛ مشکل جای پارک را شرح بده؛ پیشنهاد بده برای حل این مشکل‌ها چه کاری می‌شود کرد. دست‌کم ۱۵۰ کلمه بنویس. لازم نیست آدرسی بنویسی. نامه را این‌طور شروع کن: ⁨Dear ...............,⁩"},"model":"Dear Mr Hartley,\n\nI hope the work on your extension is going well. I know it will make a real difference to your home, but I'm afraid it is causing us a few problems, and I hope we can sort them out together.\n\nThe main difficulty is the noise early in the morning. On most days the builders start drilling at about seven o'clock, and sometimes even earlier. My wife works night shifts at the hospital and usually goes to bed at around six in the morning, so she has hardly slept properly for the past two weeks. Our baby daughter is also being woken up every day.\n\nThere is also a problem with parking. The builders' vans are often left across the front of our drive, and last Tuesday I could not get my car out and was late for an important meeting.\n\nWould it be possible to ask the builders not to start the noisy work before nine? It would also help a great deal if they could park on the side road behind the shops, where there is usually plenty of space.\n\nThank you for understanding. Do knock on our door if you would like to talk about it.\n\nKind regards,\nDaniel Moreno","moves":[{"label":{"en":"1 A friendly opening and the purpose","tr":"1 Samimi bir açılış ve amaç","fa":"۱ شروع دوستانه و هدف"},"text":"I hope the work on your extension is going well... I'm afraid it is causing us a few problems..."},{"label":{"en":"2 Bullet 1: the noise, with times and effects","tr":"2 Madde 1: gürültü, saatler ve sonuçlarla","fa":"۲ نکته‌ی ۱: سروصدا، با ساعت و پیامد"},"text":"On most days the builders start drilling at about seven o'clock... she has hardly slept properly for the past two weeks."},{"label":{"en":"3 Bullet 2: parking, one clear example","tr":"3 Madde 2: park, tek net örnek","fa":"۳ نکته‌ی ۲: جای پارک، یک مثال روشن"},"text":"The builders' vans are often left across the front of our drive, and last Tuesday I could not get my car out..."},{"label":{"en":"4 Bullet 3: polite suggestions, then a friendly close","tr":"4 Madde 3: kibar öneriler, sonra samimi kapanış","fa":"۴ نکته‌ی ۳: پیشنهادهای مؤدبانه، بعد پایان دوستانه"},"text":"Would it be possible to ask the builders not to start the noisy work before nine?... Kind regards,"}],"rubricBands":{"note":{"en":"Score each line from 0 to 3. Read the line for the score you choose: it tells you what to improve next.","tr":"Her satırı 0’dan 3’e puanla. Seçtiğin puanın satırını oku: bir sonraki adımda neyi geliştireceğini söyler.","fa":"به هر خط از ۰ تا ۳ نمره بده. توضیحِ نمره‌ای را که انتخاب می‌کنی بخوان: می‌گوید قدم بعدی چه چیزی را بهتر کنی."},"order":["task","organised","words","sentences"],"task":[{"en":"The purpose is unclear and at least one bullet is missing.","tr":"Amaç belirsiz, en az bir madde eksik.","fa":"هدف روشن نیست و دست‌کم یک نکته جا افتاده."},{"en":"All bullets are mentioned, but one or two are very thin.","tr":"Tüm maddelerden söz edilmiş ama biri ya da ikisi çok zayıf.","fa":"به همه‌ی نکته‌ها اشاره شده، اما یکی دو تا خیلی ضعیف‌اند."},{"en":"The purpose is clear early and all three bullets are covered.","tr":"Amaç baştan net, üç madde de işlenmiş.","fa":"هدف از اول روشن است و هر سه نکته پوشش داده شده‌اند."},{"en":"Clear purpose; every bullet is fully developed with useful details.","tr":"Net amaç; her madde yararlı ayrıntılarla tam geliştirilmiş.","fa":"هدف روشن؛ هر نکته با جزئیات مفید کامل شده."}],"organised":[{"en":"No paragraphs; ideas jump around.","tr":"Paragraf yok; fikirler bir yerden bir yere atlıyor.","fa":"پاراگراف ندارد؛ ایده‌ها پراکنده‌اند."},{"en":"Paragraphs, but bullets are mixed together.","tr":"Paragraflar var ama maddeler birbirine karışmış.","fa":"پاراگراف دارد، اما نکته‌ها قاطی شده‌اند."},{"en":"An opening, one paragraph per bullet and a closing.","tr":"Bir açılış, her madde için bir paragraf ve bir kapanış.","fa":"یک شروع، یک پاراگراف برای هر نکته و یک پایان."},{"en":"Each paragraph has one clear job; the letter reads smoothly.","tr":"Her paragrafın net bir işi var; mektup akıcı okunuyor.","fa":"هر پاراگراف یک کار روشن دارد؛ نامه روان خوانده می‌شود."}],"words":[{"en":"The tone does not suit the reader at all, and words are very basic.","tr":"Üslup okura hiç uymuyor, kelimeler çok temel.","fa":"لحن اصلاً به خواننده نمی‌خورد و کلمه‌ها خیلی ساده‌اند."},{"en":"The tone changes between formal and casual; simple words are repeated.","tr":"Üslup resmî ile samimi arasında gidip geliyor; basit kelimeler tekrarlanıyor.","fa":"لحن بین رسمی و خودمانی عوض می‌شود و کلمه‌های ساده تکرار می‌شوند."},{"en":"The tone suits the reader; suitable phrases for the purpose of the letter, with a few errors.","tr":"Üslup okura uygun; mektubun amacına uygun ifadeler, birkaç hata.","fa":"لحن مناسب خواننده است؛ عبارت‌های مناسب برای هدفِ نامه، با چند غلط."},{"en":"The right tone from the first line to the last, with natural, precise phrases.","tr":"İlk satırdan sona kadar doğru üslup, doğal ve yerinde ifadeler.","fa":"لحن درست از خط اول تا آخر، با عبارت‌های طبیعی و دقیق."}],"sentences":[{"en":"Mostly short sentences with frequent errors.","tr":"Çoğunlukla kısa cümleler, sık hatalar.","fa":"بیشتر جمله‌های کوتاه با غلط‌های زیاد."},{"en":"Some longer sentences; errors sometimes make the meaning unclear.","tr":"Bazı uzun cümleler; hatalar bazen anlamı belirsizleştiriyor.","fa":"چند جمله‌ی بلندتر؛ غلط‌ها گاهی معنی را نامفهوم می‌کنند."},{"en":"A mix of sentence types; errors rarely affect the meaning.","tr":"Çeşitli cümle türleri; hatalar anlamı nadiren etkiliyor.","fa":"ترکیبی از انواع جمله؛ غلط‌ها به‌ندرت روی معنی اثر می‌گذارند."},{"en":"A wide range of sentences, almost all accurate.","tr":"Çok çeşitli cümleler, neredeyse hepsi doğru.","fa":"جمله‌های خیلی متنوع، تقریباً همه درست."}]},"rubric":["Covers the task: the purpose is clear early and all three bullet points are fully covered.","Organised: one paragraph for each bullet point, with an opening and a closing that suit the reader.","Words: the right tone for the reader (formal, semi-formal or informal), with precise words.","Sentences: polite forms used correctly, a mix of sentence types and few errors."],"rubricI18n":{"tr":["Görevi karşılıyor: amaç en başta net ve üç maddenin üçü de tam olarak ele alınmış.","Düzenli: her madde için bir paragraf; okura uygun bir açılış ve kapanış.","Kelimeler: okura uygun ton (resmî, yarı resmî ya da samimi), yerinde kelimeler.","Cümleler: kibar kalıplar doğru kullanılmış, çeşitli cümle türleri ve az hata."],"fa":["تکلیف را پوشش می‌دهد: هدف از همان اول روشن است و هر سه بند کامل پوشش داده شده‌اند.","منظم است: برای هر بند یک پاراگراف، با شروع و پایانی که به خواننده می‌خورد.","کلمه‌ها: لحن مناسب برای خواننده (رسمی، نیمه‌رسمی یا دوستانه)، با کلمه‌های دقیق.","جمله‌ها: عبارت‌های مؤدبانه درست به کار رفته‌اند، ترکیبی از انواع جمله و اشتباه کم."]},"type":"writing","id":"c-x11-w1-w-gt","course":"ielts-exams","exam":"exam-11","unit":"x11-w1"},"exit":{"type":"exit","items":[{"tests":"word","point":3,"prompt":"\"The builders' vans often block our drive.\" Block means...","options":["stand in the way, so nobody can get in or out","clean","pay for"],"correct":0,"why":{"en":"Block = stop people or cars from getting past.","tr":"Block = insanların ya da arabaların geçmesini engellemek.","fa":"⁨block⁩ یعنی جلوی رد شدن آدم‌ها یا ماشین‌ها را گرفتن."}},{"tests":"paraphrase","point":3,"prompt":"Which sentence is a polite way to say \"Stop parking in front of my house\"?","options":["Never park here again.","Would it be possible for the vans to use the side road instead?","Parking is a problem."],"correct":1,"why":{"en":"It asks politely and offers an alternative.","tr":"Kibarca soruyor ve bir seçenek sunuyor.","fa":"مؤدبانه می‌پرسد و راه دیگری هم پیشنهاد می‌کند."}},{"tests":"method","point":1,"prompt":"Which beginning and ending suit a letter to a neighbour you know?","options":["Dear Mr Hartley, ... Kind regards,","Dear Sir or Madam, ... Yours faithfully,","Hey! ... Bye,"],"correct":0,"why":{"en":"Use the neighbour’s name and a semi-formal close; \"Dear Sir or Madam\" is for a reader you do not know.","tr":"Komşunun adını ve yarı resmî bir kapanış kullan; \"Dear Sir or Madam\" tanımadığın bir okur içindir.","fa":"اسم همسایه و یک پایان نیمه‌رسمی بیاور؛ «⁨Dear Sir or Madam⁩» برای خواننده‌ای است که نمی‌شناسی."}},{"tests":"trap","point":2,"prompt":"A student writes: \"Could you tell to the builders to start later?\" What is wrong?","options":["\"could\" should be \"can\"","\"tell to the builders\" should be \"tell the builders\"","\"later\" should be \"latest\""],"correct":1,"why":{"en":"Tell is followed directly by the person: tell the builders, tell him.","tr":"Tell’den hemen sonra kişi gelir: tell the builders, tell him.","fa":"بعد از ⁨tell⁩ مستقیم خود شخص می‌آید: ⁨tell the builders⁩، ⁨tell him⁩."}}],"id":"c-x11-w1-x-gt","course":"ielts-exams","exam":"exam-11","unit":"x11-w1"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
